/* ===== Writer A · Chapter 1 "夏：到来" expansion (weeks 1–12) ===== */
const c1AT=(w,d,s)=>S.week===w&&(S.day>d||(S.day===d&&S.slot>=s));
const c1S=(title,text,meta)=>say(title,text,meta);
const c1Meet=id=>{const r=rel(id);if(!r.met){r.met=true;r.like=Math.max(r.like,1)}};
const c1Letter=n=>{letter(n);log(`找到若泽的第 ${n} 封信`,`Found José's letter #${n}`,`Encontraste a carta n.º ${n} do José`)};
const c1Tired=n=>{S.energy=Math.max(0,S.energy-n)};

STORY.push(

/* W1 · first customer */
{id:'c1_first',when:()=>c1AT(1,1,1),run:()=>{const T=t('第一位客人','The first customer','O primeiro cliente');
 return {title:T,meta:t('第 1 周 · 开张','Week 1 · Opening day','Semana 1 · Dia de abertura'),text:[
  t(`中午十二点零七分，门上的铃响了。一个戴卡车帽的大个子坐到吧台前，看都没看菜单：“老样子。”`,`At 12:07 the bell over the door rings. A big man in a trucker cap takes a stool at the counter and doesn't even glance at the menu. "The usual."`,`Ao meio-dia e sete, a campainha da porta toca. Um homem enorme de boné de camionista senta-se ao balcão sem olhar para a ementa. «O costume.»`),
  t(`“老样子是什么？”你问。他看了你很久：“若泽知道。”`,`"What's the usual?" you ask. He looks at you a long time. "José knew."`,`«O que é o costume?», perguntas. Ele olha para ti muito tempo. «O José sabia.»`)],
 choices:[
  {t:t('猜一下：做一份猪排包','Guess: make him a pork cutlet sandwich','Arriscar: fazer-lhe uma bifana'),fx:()=>{S.rep+=2;stat('oficio',1)},next:()=>c1S(T,t(`他咬了一口，停住了。“蒜少了。”然后他吃完了，留下八块钱：“明天见。”`,`He takes a bite and stops. "Not enough garlic." Then he finishes it and leaves eight bucks. "See you tomorrow."`,`Dá uma dentada e pára. «Falta alho.» Depois come tudo e deixa oito dólares. «Até amanhã.»`),t('口碑 +2 · 手艺 +1','Reputation +2 · Craft +1','Reputação +2 · Ofício +1'))},
  {t:t('说实话：“我是他外甥，我不知道。您教我。”','Tell the truth: "I\'m his nephew. I don\'t know. Teach me."','Dizer a verdade: «Sou o sobrinho dele. Não sei. Ensine-me.»'),fx:()=>{S.rep+=3;stat('tex',1);S.flags.c1_firstTruth=1},next:()=>c1S(T,t(`他说若泽每天给他煎两个蛋、一根葡式香肠，配一杯黑得像机油的咖啡。“二十年，没换过。”你照做了。他喝完咖啡说：“你比他客气。他会骂我迟到。”`,`He says José fried him two eggs and a chouriço sausage every day, with coffee black as motor oil. "Twenty years. Never changed." You make it. He drains the coffee. "You're politer than him. He'd cuss me for being late."`,`Diz que o José lhe fritava todos os dias dois ovos e um chouriço, com um café preto como óleo de motor. «Vinte anos, sempre igual.» Fazes isso mesmo. Ele acaba o café. «És mais educado do que ele. Ele ralhava-me por chegar tarde.»`),t('口碑 +3 · 德州味 +1','Reputation +3 · Texanness +1','Reputação +3 · Texanidade +1'))},
  {t:`[${faceWord()}] `+t('笑一笑，送他一个蛋挞糊弄过去','Smile and slide him a free custard tart','Sorrir e oferecer-lhe um pastel de nata'),req:CHARM_REQ(40),fx:()=>{S.cash+=5;flirt()},next:()=>c1S(T,t(`他吃了蛋挞，没笑：“小子，我不是来约会的。”但他还是留了五块钱小费。`,`He eats the tart without smiling. "Son, I didn't come here on a date." He still leaves a five-dollar tip.`,`Come o pastel sem sorrir. «Rapaz, não vim cá para um encontro.» Mesmo assim, deixa cinco dólares de gorjeta.`))}]}}},

/* W1 · the grill gives out */
{id:'c1_grill',when:()=>c1AT(1,2,1),run:()=>{const T=t('烤架罢工','The grill gives out','A grelha vai-se abaixo');
 return {title:T,meta:t('第 1 周 · 午市','Week 1 · Lunch rush','Semana 1 · Hora de almoço'),text:[
  t(`午市到一半，烤架剩下的那一半也灭了，发出一声像叹气的“噗”。三桌客人在等，屋里全是煤气味。`,`Halfway through lunch the other half of the grill dies too, with a sound like a sigh. Three tables are waiting and the room reeks of gas.`,`A meio do almoço, a outra metade da grelha também se apaga, com um som de suspiro. Há três mesas à espera e a sala cheira a gás.`),
  t(`门口出现一个拄拐杖的老头：“整条主街都闻到了。我是厄尔。若泽这台烤架的脾气，只有我知道。”`,`An old man with a cane appears in the doorway. "Whole of Main Street can smell it. I'm Earl. Only man alive who knows that grill's temper."`,`Aparece à porta um velho de bengala. «A rua inteira já sente o cheiro. Sou o Earl. Só eu conheço o feitio desta grelha.»`)],
 choices:[
  {t:t('让厄尔来修','Let Earl fix it','Deixar o Earl arranjá-la'),fx:()=>{c1Meet('earl');addLike('earl',1);addTrust('earl',1);S.flags.c1_grillBy='earl'},next:()=>c1S(T,t(`他用一根晒衣铁丝和一句没法翻译的脏话把喷嘴绑好了。“若泽当年也这么修。他说葡萄牙的渔船全靠铁丝和祷告撑着。”说完他就走了，没收钱。`,`He ties the burner back with a bit of clothesline wire and a curse that doesn't translate. "José fixed it the same way. Said Portuguese fishing boats run on wire and prayer." Then he leaves without taking a cent.`,`Prende o queimador com um arame de estendal e um palavrão intraduzível. «O José arranjava-a assim. Dizia que os barcos de pesca portugueses andam a arame e a orações.» E vai-se embora sem cobrar nada.`),t('厄尔：好感 +1，信任 +1','Earl: affection +1, trust +1','Earl: afeto +1, confiança +1'))},
  {t:t('自己拆开修——建筑系画过三年管线图','Fix it yourself — three years of architecture drawings','Arranjá-la tu — três anos de desenhos de arquitetura'),req:()=>S.stats.oficio>=25||NEED(t('手艺 25','Craft 25','Ofício 25')),fx:()=>{stat('oficio',3);S.flags.c1_grillBy='self'},next:()=>c1S(T,t(`喷嘴里塞着一团烧焦的纸，像是信纸的一角，只剩几个字：“亲爱的妹……”你把它吹干净，烤架重新点着了。`,`The burner is clogged with a scorched wad of paper — the corner of a letter. Only a few words survive: "Dear sis—". You blow it clean and the grill catches.`,`O queimador está entupido com um pedaço de papel queimado — o canto de uma carta. Só sobram umas palavras: «Querida mana…». Limpas tudo e a grelha volta a acender.`),t('手艺 +3','Craft +3','Ofício +3'))},
  {t:t('打电话叫韦科的维修工（$150）','Call a repairman from Waco ($150)','Chamar um técnico de Waco ($150)'),req:MONEY(150),fx:()=>{S.cash-=150;S.rep-=2;S.flags.c1_grillBy='pro'},next:()=>c1S(T,t(`维修工三个小时后才到，收了钱，说这台烤架“该进博物馆了”。客人走了一半。`,`The repairman shows up three hours later, takes the money and says the grill "belongs in a museum." Half the customers have gone.`,`O técnico só chega três horas depois, cobra e diz que a grelha «devia estar num museu». Metade dos clientes já foi embora.`),t('现金 −$150 · 口碑 −2','Cash −$150 · Reputation −2','Dinheiro −$150 · Reputação −2'))}]}}},

/* W1 · the plastic chair */
{id:'c1_chair',when:()=>c1AT(1,5,2),run:()=>{
 return {title:t('后门的塑料椅','The plastic chair','A cadeira de plástico'),meta:t('第 1 周 · 夜','Week 1 · Night','Semana 1 · Noite'),text:[
  t(`打烊以后你从后门出去透气。店后是一块空地，杂草齐腰，萤火虫一闪一闪。门边有一把白色塑料椅，椅脚陷进了土里——有人在这儿坐过很多个晚上，脸朝着空地。`,`After closing you step out the back door for air. Behind the shop is an empty lot, weeds waist-high, fireflies blinking. By the door sits a white plastic chair, its legs sunk into the dirt. Someone sat here a lot of nights, facing the lot.`,`Depois de fechar sais pela porta das traseiras para apanhar ar. Atrás do restaurante há um terreno vazio, ervas pela cintura, pirilampos a piscar. Junto à porta há uma cadeira de plástico branca, com as pernas enterradas na terra. Alguém se sentou aqui muitas noites, virado para o terreno.`),
  t(`空地尽头立着一座生锈的水塔，上面的字掉了一半：“圣鲁伊斯罐……”你坐下来。从这个角度什么都看不见，只有草、水塔和很大的天。`,`At the far end stands a rusted water tower, half its letters gone: "SAN LUÍS PACK…". You sit down. From here there's nothing to see but grass, the tower and a very big sky.`,`Ao fundo ergue-se uma torre de água ferrugenta, com metade das letras caídas: «SAN LUÍS PACK…». Sentas-te. Daqui não se vê nada além de erva, da torre e de um céu enorme.`)],
 choices:[
  {t:t('坐到萤火虫散了','Sit until the fireflies are gone','Ficar até os pirilampos desaparecerem'),fx:()=>{stat('saud',4);S.flags.c1_chair='sat'}},
  {t:t('把椅子从土里拔出来，擦干净','Pull the chair out of the dirt and wipe it clean','Tirar a cadeira da terra e limpá-la'),fx:()=>{stat('tex',1);S.flags.c1_chair='cleaned'}},
  {t:t('给妈妈拍一张水塔的照片，没发出去','Take a photo of the tower for Mom, and don\'t send it','Tirar uma fotografia da torre para a mãe, e não a enviar'),fx:()=>{stat('saud',2);S.flags.c1_chair='photo'}}]}}},

/* W2 · mistaken for Mexican */
{id:'c1_mexican',when:()=>c1AT(2,3,1),run:()=>{const T=t('“你是墨西哥哪儿的？”','"What part of Mexico?"','«De que parte do México?»');
 return {title:T,meta:t('文化误会','Culture clash','Choque cultural'),text:[
  t(`一家五口进门，爸爸用西班牙语点菜：两份玉米卷饼，一份辣酱肉馅饼。你听懂了七成，用葡语回了一句。`,`A family of five walks in and the father orders in Spanish: two burritos, one enchilada plate. You understand about seventy percent and answer in Portuguese.`,`Entra uma família de cinco e o pai pede em espanhol: dois burritos e uma enchilada. Percebes uns setenta por cento e respondes em português.`),
  t(`他高兴地一拍桌子：“瓦哈卡来的？”你说里斯本。他想了想：“那是西班牙哪儿？”`,`He slaps the table, delighted. "Oaxaca?" You say Lisbon. He thinks about it. "What part of Spain is that?"`,`Ele bate na mesa, todo contente. «Oaxaca?» Dizes Lisboa. Ele pensa um bocado. «Isso é em que parte de Espanha?»`)],
 choices:[
  {t:t('用葡西混合语跟他聊下去','Keep chatting in your Portuguese-Spanish mash-up','Continuar a conversa em portunhol'),fx:()=>{stat('tex',2);S.rep+=2},next:()=>c1S(T,t(`你们聊了二十分钟，各说各的语言，居然全听懂了。他走前说下周带表弟来：“他也是从很远的地方来的——圣安东尼奥。”`,`You talk for twenty minutes, each in your own language, and somehow understand everything. On his way out he says he'll bring his cousin next week. "He's from far away too — San Antonio."`,`Falam vinte minutos, cada um na sua língua, e percebem-se perfeitamente. À saída diz que traz o primo na semana que vem. «Ele também vem de longe — de San Antonio.»`))},
  {t:t('拿餐巾纸画一张伊比利亚半岛地图','Draw him a map of the Iberian Peninsula on a napkin','Desenhar-lhe um mapa da Península Ibérica num guardanapo'),fx:()=>{stat('saud',3);S.rep+=1;S.lusoThisWeek=true},next:()=>c1S(T,t(`你画得太好了，建筑系没白读。他把餐巾纸叠起来放进钱包：“给我女儿。她下周考地理。”`,`You draw it far too well — architecture school wasn't wasted. He folds the napkin into his wallet. "For my daughter. She's got a geography test next week."`,`Desenhas bem demais — o curso de arquitetura não foi em vão. Ele dobra o guardanapo e guarda-o na carteira. «É para a minha filha. Tem teste de geografia para a semana.»`))},
  {t:`[${faceWord()}] `+t('“今天我就是墨西哥人。您想吃什么我都会做。”','"Today I\'m Mexican. Whatever you want, I can make it."','«Hoje sou mexicano. O que quiser, eu faço.»'),req:CHARM_REQ(50),fx:()=>{stat('tex',3);S.rep+=3},next:()=>c1S(T,t(`你没有玉米饼，只有猪排包。他吃完说，这是他吃过最好的“西班牙卷饼”。你决定不纠正了。回厨房的路上，你觉得自己好像把什么东西弄丢了一点。`,`You have no tortillas, only pork cutlet sandwiches. He finishes and declares it the best "Spanish burrito" he's ever had. You decide not to correct him. Walking back to the kitchen, you feel like you've misplaced a small piece of something.`,`Não tens tortilhas, só bifanas. Ele acaba e declara que foi o melhor «burrito espanhol» da vida dele. Decides não o corrigir. A caminho da cozinha, sentes que perdeste um bocadinho de qualquer coisa.`))}]}}},

/* W2 · first thunderstorm */
{id:'c1_storm',when:()=>c1AT(2,5,2),run:()=>{const T=t('第一场德州雷暴','Your first Texas thunderstorm','A primeira trovoada do Texas');
 return {title:T,meta:t('第 2 周 · 傍晚','Week 2 · Evening','Semana 2 · Fim de tarde'),text:[
  t(`五点天还是蓝的。五点二十，西边的天变成了瘀青的颜色。五点半，冰雹砸在铁皮屋顶上，像有人往上面倒了一卡车玻璃弹珠。然后停电了。`,`At five the sky is blue. At five-twenty the west turns the color of a bruise. At five-thirty hail hits the tin roof like someone tipped a truckload of marbles onto it. Then the power goes.`,`Às cinco o céu está azul. Às cinco e vinte, a oeste, fica da cor de uma nódoa negra. Às cinco e meia o granizo bate no telhado de zinco como se alguém despejasse um camião de berlindes. Depois falta a luz.`),
  t(`店里还有六个大学生、一个卡车司机，和一台正在化冻的冰箱。司机看了一眼手机：“龙卷风警报。没事，只是‘警报’。”`,`Still inside: six college kids, one trucker and a fridge that's starting to thaw. The trucker checks his phone. "Tornado warning. Relax, it's just a warning."`,`Lá dentro ainda estão seis estudantes, um camionista e um frigorífico a descongelar. O camionista olha para o telemóvel. «Alerta de tornado. Calma, é só um alerta.»`)],
 choices:[
  {t:t('点上蜡烛，在炭火那半边继续烤','Light candles and keep grilling on the charcoal side','Acender velas e continuar a grelhar do lado do carvão'),req:()=>S.stats.oficio>=25||NEED(t('手艺 25','Craft 25','Ofício 25')),fx:()=>{S.cash+=60;S.rep+=3;S.online=clamp(S.online+4,0,100);stat('tex',2)},next:()=>c1S(T,t(`你在黑暗里烤了四十条沙丁鱼。大学生们用手机电筒照着你，有人放起了法多，雷声给它伴奏。第二天网上有人写：“世界末日那天，我想待在这家店。”`,`You grill forty sardines in the dark. The students light you with their phones; someone puts on fado and the thunder keeps time. Next day someone posts: "When the world ends, I want to be in this place."`,`Grelhas quarenta sardinhas às escuras. Os estudantes iluminam-te com os telemóveis, alguém põe fado e a trovoada faz de percussão. No dia seguinte alguém escreve na internet: «Quando o mundo acabar, quero estar neste sítio.»`),t('现金 +$60 · 口碑 +3 · 线上 +4','Cash +$60 · Reputation +3 · Online +4','Dinheiro +$60 · Reputação +3 · Online +4'))},
  {t:t('听司机的，带大家躲进冷库','Listen to the trucker: everyone into the walk-in cooler','Ouvir o camionista: toda a gente para a câmara frigorífica'),fx:()=>{stat('tex',3);S.rep+=1},next:()=>c1S(T,t(`九个人挤在冷库里，冻猪肉顶着你的后背。二十分钟后警报解除，大家出来的时候已经成了朋友。司机拍拍你：“欢迎来到德州。”`,`Nine people crammed in the cooler, frozen pork pressed against your back. Twenty minutes later it's all clear, and everyone walks out friends. The trucker claps your shoulder. "Welcome to Texas."`,`Nove pessoas apertadas na câmara, com porco congelado encostado às tuas costas. Vinte minutos depois o alerta acaba e saem todos amigos. O camionista dá-te uma palmada. «Bem-vindo ao Texas.»`))},
  {t:t('关门，上楼给里斯本打电话','Close up and call Lisbon from upstairs','Fechar e ligar para Lisboa lá de cima'),fx:()=>{stat('saud',5);S.rep-=1;S.lusoThisWeek=true},next:()=>c1S(T,t(`妈妈说里斯本今天二十二度，有点小风。你说这边也挺好的。窗外一道闪电，把整条主街照成白色。`,`Mom says it's twenty-two degrees in Lisbon with a little breeze. You say it's nice here too. Outside, lightning turns all of Main Street white.`,`A mãe diz que em Lisboa estão vinte e dois graus e uma brisa. Dizes que aqui também está bom. Lá fora, um relâmpago pinta a rua principal de branco.`))}]}}},

/* W3 · Tommy, Little Dale and the Wi-Fi */
{id:'c1_wifi',when:()=>c1AT(3,2,2),run:()=>{const T=t('蹭网的人','The Wi-Fi squatters','Os penduras da internet');
 return {title:T,meta:t('第 3 周 · 夜','Week 3 · Night','Semana 3 · Noite'),text:[
  t(`两个高中生每天晚上七点准时坐到插座边那张桌子。瘦高、话多的叫汤米；戴眼镜、一句话不说的是戴尔牧师的小儿子，大家叫他小戴尔。他们点一杯水，蹭四个小时无线网。`,`Every night at seven, two high schoolers take the table by the outlet. The tall talkative one is Tommy; the quiet one in glasses is Pastor Dale's youngest, Little Dale. They order one glass of water and ride the Wi-Fi for four hours.`,`Todas as noites, às sete em ponto, dois miúdos do liceu sentam-se na mesa ao pé da tomada. O alto e falador é o Tommy; o calado de óculos é o filho mais novo do Pastor Dale, a quem chamam pequeno Dale. Pedem um copo de água e passam quatro horas na internet.`),
  t(`今晚汤米终于开口：“那个……密码是不是被改回去了？若泽以前的密码是‘圣安东尼九六’。”你不知道舅舅为什么用这个当密码。圣安东尼是里斯本的主保圣人。可是“九六”呢？`,`Tonight Tommy finally speaks up. "Um… did the password change back? José's used to be SantoAntonio96." You have no idea why your uncle chose it. Saint Anthony is Lisbon's patron saint. But ninety-six?`,`Esta noite o Tommy ganha coragem. «Hum… a palavra-passe mudou? A do José era SantoAntonio96.» Não fazes ideia porque o teu tio a escolheu. Santo António é o padroeiro de Lisboa. Mas noventa e seis?`)],
 choices:[
  {t:t('让他们免费用，条件是在网上写好评','Let them use it free, if they post a good review','Deixá-los usar de graça, se escreverem uma boa crítica'),fx:()=>{S.online=clamp(S.online+5,0,100);S.rep+=1;S.flags.c1_wifi='free'},next:()=>c1S(T,t(`第二天小戴尔在网上发了一篇三百字的评价。汤米在下面留言：“他爸不知道他来这儿。”`,`Next day Little Dale posts a three-hundred-word review. Tommy comments underneath: "his dad doesn't know he comes here."`,`No dia seguinte o pequeno Dale publica uma crítica de trezentas palavras. O Tommy comenta por baixo: «o pai dele não sabe que ele vem cá».`),t('线上 +5 · 口碑 +1','Online +5 · Reputation +1','Online +5 · Reputação +1'))},
  {t:t('立规矩：一杯咖啡换两小时','New rule: one coffee buys two hours','Regra nova: um café dá direito a duas horas'),fx:()=>{S.cash+=6;stat('tex',1);S.flags.c1_wifi='coffee'},next:()=>c1S(T,t(`汤米抗议了三分钟，然后掏出一张皱巴巴的五块钱。小戴尔小声说：“其实很公平。”这是你第一次听见他说话。`,`Tommy protests for three minutes, then digs out a crumpled five. Little Dale says quietly, "That's actually fair." It's the first time you've heard him speak.`,`O Tommy protesta três minutos e depois tira uma nota de cinco toda amarrotada. O pequeno Dale diz baixinho: «Até é justo.» É a primeira vez que o ouves falar.`))},
  {t:t('让汤米周末来跑堂，用网费抵工钱','Have Tommy run plates on weekends in exchange','Pôr o Tommy a servir ao fim de semana em troca'),req:()=>S.rep>=12||NEED(t('口碑 12','Reputation 12','Reputação 12')),fx:()=>{S.rep+=2;S.flags.c1_wifi='work'},next:()=>c1S(T,t(`汤米周六来了，摔了两个盘子，记住了所有常客的名字。`,`Tommy shows up Saturday, breaks two plates and learns every regular's name.`,`O Tommy aparece no sábado, parte dois pratos e decora o nome de todos os clientes habituais.`))}]}}},

/* W3 · Austin wholesale market */
{id:'c1_austin',when:()=>c1AT(3,4,0),run:()=>{const T=t('奥斯汀批发市场','The Austin wholesale market','O mercado abastecedor de Austin');
 return {title:T,meta:t('第 3 周 · 清晨','Week 3 · Early morning','Semana 3 · De madrugada'),text:[
  t(`葡萄牙货在圣鲁伊斯买不到。厄尔说奥斯汀东边有个批发市场，有个亚速尔人在那儿卖鳕鱼干和橄榄油。问题是你不会开车，奥斯汀在一百多公里外。`,`You can't get Portuguese goods in San Luís. Earl says there's a wholesale market on Austin's east side where an Azorean sells salt cod and olive oil. Problem is, you can't drive, and Austin is seventy miles away.`,`Em San Luís não há produtos portugueses. O Earl diz que no lado leste de Austin há um mercado abastecedor onde um açoriano vende bacalhau e azeite. O problema é que não sabes conduzir e Austin fica a mais de cem quilómetros.`)],
 choices:[
  {t:t('借厄尔的老福特自己开（$120 进货）','Borrow Earl\'s old Ford and drive ($120 of stock)','Pedir a velha Ford do Earl e ir a conduzir ($120 de compras)'),req:()=>S.course.drive<1?NEED(t('驾驶课 1','Driving lesson 1','Aula de condução 1')):(S.cash>=120||t('钱不够','Not enough money','Não tens dinheiro')),fx:()=>{S.cash-=120;S.incoming+=10;stat('tex',3);S.flags.c1_austin='drove'},next:()=>c1S(T,t(`你在州际公路上开了一个小时，被十七辆卡车超了车。市场里的亚速尔老板一听你开口就笑：“里斯本人！你们说话太快了。”`,`An hour on I-35, passed by seventeen trucks. The Azorean at the market laughs the moment you open your mouth. "Lisbon! You people talk too fast."`,`Uma hora na I-35, ultrapassado por dezassete camiões. O açoriano do mercado ri-se mal abres a boca. «Lisboeta! Vocês falam depressa demais.»`),t('本周末到货 10 份进口货 · 德州味 +3','10 import units arrive this weekend · Texanness +3','Chegam 10 doses importadas no fim de semana · Texanidade +3'))},
  {t:t('搭露西娅送牛肉的车（$120 进货）','Ride along on Lucía\'s beef delivery ($120 of stock)','Ir com a Lucía na entrega de carne ($120 de compras)'),req:()=>!rel('lucia').met?NEED(t('认识露西娅','Know Lucía','Conhecer a Lucía')):(S.cash>=120||t('钱不够','Not enough money','Não tens dinheiro')),fx:()=>{S.cash-=120;S.incoming+=8;addLike('lucia',1);addTrust('lucia',1);S.flags.c1_austin='lucia'},next:()=>c1S(T,t(`一路上她只说了三句话，其中一句是“别碰收音机”。回来的路上她把车停在路边，让你看了二十分钟日落，什么也没说。`,`She says three things the whole way, one of which is "Don't touch the radio." On the way back she pulls over and lets you watch the sunset for twenty minutes without a word.`,`Durante a viagem diz três frases, uma delas «não mexas no rádio». No regresso encosta a carrinha e deixa-te ver o pôr do sol durante vinte minutos sem dizer nada.`),t('本周末到货 8 份 · 露西娅：好感 +1，信任 +1','8 import units this weekend · Lucía: affection +1, trust +1','Chegam 8 doses · Lucía: afeto +1, confiança +1'))},
  {t:t('坐灰狗巴士去（$140）','Take the Greyhound ($140)','Ir de Greyhound ($140)'),req:MONEY(140),fx:()=>{S.cash-=140;S.incoming+=6;stat('saud',2);S.flags.c1_austin='bus'},next:()=>c1S(T,t(`来回六个小时。你抱着一箱鳕鱼干坐在最后一排。奥斯汀街上到处是和你一样年纪的人。你第一次想：住在这儿会是什么样？`,`Six hours round trip, a box of salt cod on your lap in the back row. Austin's streets are full of people your age. For the first time you wonder what living here would be like.`,`Seis horas ida e volta, com uma caixa de bacalhau ao colo no último banco. As ruas de Austin estão cheias de gente da tua idade. Pela primeira vez perguntas-te como seria viver ali.`),t('本周末到货 6 份','6 import units this weekend','Chegam 6 doses no fim de semana'))},
  {t:t('算了，下次再说','Forget it, maybe next time','Deixa estar, fica para a próxima'),fx:()=>stat('saud',3)}]}}},

/* W3 · Earl on José */
{id:'c1_earl',when:()=>c1AT(3,6,2),run:()=>{const T=t('厄尔讲若泽','Earl on José','O Earl fala do José');c1Meet('earl');
 return {title:T,meta:t('孤星酒吧 · 周六夜','Lone Star Saloon · Saturday night','Lone Star Saloon · Sábado à noite'),text:[
  t(`周六夜里，厄尔破例给你倒了第二杯。“你想知道你舅舅？”他擦同一个杯子擦了很久。`,`Saturday night, and Earl breaks his own rule and pours you a second. "You want to know about your uncle?" He polishes the same glass for a long time.`,`Sábado à noite, o Earl quebra a regra e serve-te um segundo copo. «Queres saber do teu tio?» Fica muito tempo a limpar o mesmo copo.`),
  t(`“九八年他从罐头厂出来，口袋里只有一张地契，那块地连蛇都不住。他在上面搭了个铁皮棚卖猪排包，一卖二十年。没喝醉过一次。坐我这儿永远脸朝门。”`,`"Ninety-eight he walks out of the cannery with nothing but a deed to a lot even snakes wouldn't live on. Puts up a tin shed and sells pork sandwiches for twenty years. Never once drunk. Always sat facing the door."`,`«Em noventa e oito saiu da fábrica de conservas só com a escritura de um terreno onde nem as cobras viviam. Montou um barracão de zinco e vendeu bifanas vinte anos. Nunca se embebedou. Sentava-se sempre virado para a porta.»`),
  t(`“有一回他喝到第二杯，说：‘我把一条船留在海里了。’我问什么船。他说：‘一条不该出海的船。’然后付了钱就走了。”`,`"One time, second glass, he says: 'I left a boat in the sea.' I ask what boat. He says, 'One that never should've gone out.' Then he paid and left."`,`«Uma vez, ao segundo copo, disse: "Deixei um barco no mar." Perguntei que barco. Disse: "Um que nunca devia ter saído." Depois pagou e foi-se embora.»`)],
 choices:[
  {t:t('问罐头厂的事','Ask about the cannery','Perguntar pela fábrica'),fx:()=>{addTrust('earl',1);S.flags.c1_askedCannery=1},next:()=>c1S(T,t(`厄尔的手停了一下。“那是汉克·博伊德的厂子。你去问汉克——哦，他快不行了。那就别问了。”`,`Earl's hand stops. "That was Hank Boyd's plant. Go ask Hank — oh, he's dying. So don't."`,`A mão do Earl pára. «Era a fábrica do Hank Boyd. Vai perguntar ao Hank — ah, está a morrer. Então não perguntes.»`))},
  {t:t('问那条船','Ask about the boat','Perguntar pelo barco'),fx:()=>{stat('saud',3);addLike('earl',1)},next:()=>c1S(T,t(`“我是开坦克的，孩子，不懂船。”他把酒瓶收了起来。“但我懂一个男人不想回家是什么样子。你舅舅就是那个样子。”`,`"I drove tanks, son. Don't know boats." He puts the bottle away. "But I know what a man looks like when he don't want to go home. Your uncle looked like that."`,`«Eu conduzia tanques, filho. Não percebo de barcos.» Guarda a garrafa. «Mas sei como é um homem que não quer voltar para casa. O teu tio era assim.»`),t('乡愁 +3 · 厄尔：好感 +1','Homesickness +3 · Earl: affection +1','Saudade +3 · Earl: afeto +1'))},
  {t:t('举杯：“敬若泽。”','Raise your glass: "To José."','Erguer o copo: «Ao José.»'),req:()=>rel('earl').trust>=1||NEED(t('厄尔信任 1','Earl\'s trust 1','Confiança do Earl 1')),fx:()=>{addTrust('earl',1);addLike('earl',1);S.rep+=1},next:()=>c1S(T,t(`厄尔看了你一眼，跟你碰了杯。“他会喜欢你的。他讨厌所有人，但他会喜欢你。”`,`Earl looks at you, then clinks your glass. "He'd have liked you. Hated everybody, but he'd have liked you."`,`O Earl olha para ti e brinda. «Ele ia gostar de ti. Detestava toda a gente, mas de ti ia gostar.»`))}]}}},

/* W4 · sweet tea */
{id:'c1_tea',when:()=>c1AT(4,2,1),run:()=>{const T=t('甜茶事件','The sweet tea incident','O escândalo do chá doce');
 return {title:T,meta:t('小城喜剧','Small-town comedy','Comédia de vila'),text:[
  t(`教会的三位太太点了冰茶。你照里斯本的习惯：不加糖，一片柠檬，一枝薄荷。`,`Three church ladies order iced tea. You make it Lisbon-style: no sugar, a slice of lemon, a sprig of mint.`,`Três senhoras da igreja pedem chá gelado. Fazes à moda de Lisboa: sem açúcar, uma rodela de limão, um raminho de hortelã.`),
  t(`第一位喝了一口，放下杯子，像被冒犯了。第二位问你是不是“在搞什么健康饮食”。第三位只说：“亲爱的，上帝保佑你的心。”厄尔后来告诉你，在德州，这句话的意思是“你这个可怜的傻孩子”。`,`The first takes a sip and sets the glass down like she's been insulted. The second asks if you're "doing some kind of health thing." The third just says, "Well, bless your heart, honey." Earl later explains that in Texas this means "you poor fool."`,`A primeira bebe um gole e pousa o copo como se a tivessem ofendido. A segunda pergunta se aquilo é «alguma dieta». A terceira diz só: «Que Deus abençoe esse coraçãozinho, querido.» O Earl explica-te depois que, no Texas, isto quer dizer «coitadinho, que tolo».`)],
 choices:[
  {t:t('入乡随俗：熬一锅糖浆，冰茶甜到牙疼','When in Texas: boil syrup, make it tooth-achingly sweet','Em Roma sê romano: xarope até doerem os dentes'),fx:()=>{stat('tex',4);S.rep+=2},next:()=>c1S(T,t(`下个星期太太们又来了。第一位喝了一口，点点头：“现在你是我们的人了。”你偷偷算了一下，一杯里有十一勺糖。`,`Next week the ladies are back. The first one sips and nods. "Now you're one of us." You do the math in secret: eleven spoons of sugar per glass.`,`Na semana seguinte as senhoras voltam. A primeira bebe e acena. «Agora és dos nossos.» Fazes as contas às escondidas: onze colheres de açúcar por copo.`))},
  {t:t('坚持：菜单上写“里斯本冰茶”，配蛋挞','Hold firm: list it as "Lisbon iced tea," served with a custard tart','Manter: pôr na ementa «chá gelado de Lisboa», com pastel de nata'),fx:()=>{S.lusoThisWeek=true;S.rep+=1;S.online=clamp(S.online+2,0,100)},next:()=>c1S(T,t(`太太们没再点。但大学生开始拍照发网上，管它叫“欧洲冰茶”，一杯多收一块钱。`,`The ladies never order it again. But the college kids start posting photos of "European iced tea," and it sells for a dollar more.`,`As senhoras nunca mais pedem. Mas os estudantes começam a publicar fotos do «chá gelado europeu», que se vende a mais um dólar.`))},
  {t:t('两样都上：甜的叫“德州”，不甜的叫“里斯本”','Serve both: sweet is "Texas," unsweet is "Lisbon"','Servir os dois: o doce é «Texas», o sem açúcar é «Lisboa»'),req:()=>S.stats.oficio>=30||NEED(t('手艺 30','Craft 30','Ofício 30')),fx:()=>{stat('tex',2);S.rep+=3;S.lusoThisWeek=true},next:()=>c1S(T,t(`菜单上多了一行。厄尔看了一眼：“你这是在搞外交。”`,`The menu grows a line. Earl reads it. "You're running a foreign policy now."`,`A ementa ganha uma linha. O Earl lê. «Agora fazes diplomacia.»`))}]}}},

/* W4 · Savannah's flowers */
{id:'c1_flowers',when:()=>c1AT(4,5,1),run:()=>{const T=t('萨凡纳的花','Savannah\'s flowers','As flores da Savannah');c1Meet('savannah');
 return {title:T,meta:t('星期五 · 中午','Friday · Noon','Sexta-feira · Meio-dia'),text:[
  t(`星期五中午，花店的萨凡纳抱着一桶向日葵推门进来，放在你的窗台上。“若泽每个星期五给我送一份猪排包，我每个星期五给他换一桶花。二十年。”`,`Friday noon, Savannah from the flower shop shoulders the door open with a bucket of sunflowers and sets it on your windowsill. "Every Friday José brought me a pork sandwich, and every Friday I changed his flowers. Twenty years."`,`Sexta ao meio-dia, a Savannah da florista entra com um balde de girassóis e pousa-o no parapeito. «Todas as sextas o José levava-me uma bifana e todas as sextas eu trocava-lhe as flores. Vinte anos.»`),
  t(`她看着空空的窗台：“他走了以后，我还是每个星期五扎一束。扎好了才想起来，没人收了。”`,`She looks at the empty sill. "After he passed I kept making a bunch every Friday. Then I'd remember there was nobody to take it."`,`Olha para o parapeito vazio. «Depois de ele morrer continuei a fazer um ramo todas as sextas. Só depois me lembrava de que já não havia quem o recebesse.»`)],
 choices:[
  {t:t('做一份猪排包给她，就像若泽那样','Make her a pork sandwich, the way José did','Fazer-lhe uma bifana, como o José fazia'),fx:()=>{addLike('savannah',1);addTrust('savannah',2);S.flags.c1_fridays=1;log('和萨凡纳的星期五约定恢复了','The Friday exchange with Savannah is back on','A troca das sextas com a Savannah recomeçou')},next:()=>c1S(T,t(`她站在柜台边吃完，擦了擦手：“蒜放多了。他也总放多。”从那天起，星期五又有人换花了。`,`She eats it standing at the counter and wipes her hands. "Too much garlic. He always overdid it too." From then on, the Friday flowers come again.`,`Come-a de pé ao balcão e limpa as mãos. «Alho a mais. Ele também exagerava sempre.» A partir desse dia, as flores de sexta voltam.`),t('萨凡纳：好感 +1，信任 +2','Savannah: affection +1, trust +2','Savannah: afeto +1, confiança +2'))},
  {t:`[${faceWord()}] `+t('“那以后的花，都送给我吧。”','"Then from now on, bring them to me."','«Então a partir de agora, traz-mas a mim.»'),req:CHARM_REQ(50),fx:()=>{addLike('savannah',2);flirt()},next:()=>c1S(T,t(`她笑了，但眼睛没笑。“嘴真甜。若泽可从来不说这种话。”`,`She smiles, but not with her eyes. "Sweet talker. José never said a thing like that."`,`Sorri, mas os olhos não. «Que lábia. O José nunca dizia coisas destas.»`))},
  {t:t('问她，若泽为什么喜欢向日葵','Ask her why José liked sunflowers','Perguntar-lhe porque o José gostava de girassóis'),fx:()=>{addTrust('savannah',1);stat('saud',2)},next:()=>c1S(T,t(`“他说向日葵永远朝着一个方向。他说他很羡慕。”她顿了顿，“我一直没问他，羡慕什么。”`,`"He said sunflowers always face one direction. Said he envied them." She pauses. "I never did ask him what he meant."`,`«Dizia que os girassóis estão sempre virados para o mesmo lado. Que tinha inveja deles.» Faz uma pausa. «Nunca lhe perguntei porquê.»`))}]}}},

/* W5 · church potluck */
{id:'c1_potluck',when:()=>!!S.flags.church&&c1AT(5,7,0),run:()=>{const T=t('教堂聚餐','The church potluck','O almoço partilhado da igreja');
 return {title:T,meta:t('圣安东尼教堂 · 星期天','St. Anthony\'s · Sunday','Igreja de Santo António · Domingo'),text:[
  t(`礼拜结束，阿尔贝蒂娜拉你去地下室聚餐。长桌上摆着十七种焗菜，中间是一盆绿色果冻，里面冻着胡萝卜丝和小棉花糖。`,`After the service Albertina drags you down to the basement potluck. Seventeen casseroles on a long table, and in the middle a bowl of green gelatin with shredded carrot and mini marshmallows suspended in it.`,`Depois da missa, a Albertina leva-te ao almoço na cave. Dezassete tachos de forno numa mesa comprida e, ao meio, uma taça de gelatina verde com cenoura ralada e marshmallows lá dentro.`),
  t(`“这是我们葡萄牙的传统。”一位席尔瓦老先生骄傲地说。你非常确定葡萄牙没有这个传统。阿尔贝蒂娜在你耳边说：“他祖母是从亚速尔来的。他这辈子只去过休斯敦。别说破。”`,`"It's an old Portuguese tradition," old Mr. Silva announces proudly. You are very sure it is not. Albertina whispers, "His grandmother came from the Azores. He's never been farther than Houston. Don't you dare."`,`«É uma tradição portuguesa», anuncia o velho senhor Silva, todo orgulhoso. Tens a certeza absoluta de que não é. A Albertina sussurra-te: «A avó dele veio dos Açores. Ele nunca passou de Houston. Nem te atrevas.»`)],
 choices:[
  {t:t('舀一大勺果冻：“跟我外婆做的一样。”','Take a big scoop: "Just like my grandmother\'s."','Servir-te bem: «Igualzinha à da minha avó.»'),fx:()=>{addLike('albertina',2);S.rep+=3;stat('tex',2)},next:()=>c1S(T,t(`席尔瓦先生眼眶红了。你吃完了一整碗。阿尔贝蒂娜在桌子底下捏了捏你的手。`,`Mr. Silva's eyes go wet. You finish the whole bowl. Under the table, Albertina squeezes your hand.`,`O senhor Silva fica de olhos húmidos. Comes a taça inteira. Debaixo da mesa, a Albertina aperta-te a mão.`),t('阿尔贝蒂娜：好感 +2 · 口碑 +3','Albertina: affection +2 · Reputation +3','Albertina: afeto +2 · Reputação +3'))},
  {t:t('下周带一锅真正的羽衣甘蓝汤来','Bring a pot of real kale soup next week','Trazer uma panela de caldo verde a sério na semana seguinte'),fx:()=>{S.lusoThisWeek=true;addTrust('albertina',1);S.rep+=2;stat('saud',2)},next:()=>c1S(T,t(`下个星期天，老人们排着队喝汤。有一个人喝着喝着冒出一句葡语——“真好喝”——然后自己吓了一跳，好像忘了自己会说。`,`Next Sunday the old folks queue up for soup. One of them, mid-spoonful, says a word in Portuguese — "delicious" — and startles himself, as if he'd forgotten he knew it.`,`No domingo seguinte, os velhotes fazem fila para a sopa. Um deles, a meio da colher, diz «que bom» em português — e assusta-se, como se se tivesse esquecido de que sabia.`))},
  {t:t('用葡语唱一首赞美诗','Sing a hymn in Portuguese','Cantar um hino em português'),req:()=>S.stats.saud>=50||NEED(t('乡愁 50','Homesickness 50','Saudade 50')),fx:()=>{addLike('albertina',2);S.rep+=4;stat('saud',3);S.lusoThisWeek=true},next:()=>c1S(T,t(`地下室安静下来。你唱到第二段，阿尔贝蒂娜跟着唱了起来，用的是六十年前的词。你们谁都没停。`,`The basement goes quiet. By the second verse Albertina is singing with you, in words from sixty years ago. Neither of you stops.`,`A cave fica em silêncio. À segunda estrofe a Albertina já canta contigo, com a letra de há sessenta anos. Nenhum dos dois pára.`),t('阿尔贝蒂娜：好感 +2 · 口碑 +4','Albertina: affection +2 · Reputation +4','Albertina: afeto +2 · Reputação +4'))}]}}},

/* W6 · Marisol's lesson */
{id:'c1_marisol',when:()=>!!S.flags.ranch&&c1AT(6,4,1),run:()=>{const T=t('玛丽索尔的烤肉课','Marisol\'s barbecue lesson','A aula de churrasco da Marisol');c1Meet('marisol');
 return {title:T,meta:t('雷耶斯牧场 · 厨房','Reyes Ranch · The kitchen','Rancho Reyes · A cozinha'),text:[
  t(`贝托说牧场周四烤肉：“来看，别说话。”你到的时候，玛丽索尔已经在牧豆木火堆前守了十一个小时。`,`Beto said they smoke meat at the ranch on Thursdays. "Come watch. Don't talk." When you arrive, Marisol has been minding the mesquite fire for eleven hours.`,`O Beto disse que às quintas se fuma carne no rancho. «Vem ver. Não fales.» Quando chegas, a Marisol já está há onze horas de volta da fogueira de algaroba.`),
  t(`她让你按那块牛胸肉：“像按你自己的手心。软，但会弹回来。到这时候才算好。”你说里斯本烤沙丁鱼只要四分钟。她看你的眼神，像在看一个说“月亮很近”的小孩。`,`She has you press the brisket. "Like pressing your own palm. Soft, but it pushes back. That's when it's done." You mention that in Lisbon sardines take four minutes. She looks at you like a child who just said the moon is close.`,`Manda-te carregar no peito de vaca. «Como quem carrega na palma da mão. Mole, mas volta para trás. Só aí está pronto.» Dizes que em Lisboa as sardinhas levam quatro minutos. Ela olha para ti como para uma criança que diz que a lua está perto.`)],
 choices:[
  {t:t('留下来，守一整夜的火','Stay and tend the fire all night','Ficar a guardar o lume a noite inteira'),fx:()=>{stat('oficio',5);stat('tex',3);addTrust('marisol',2);S.flags.c1_marisol='night';c1Tired(3)},next:()=>c1S(T,t(`凌晨三点，她递给你一杯咖啡，讲起她在蒙特雷的奶奶。早上七点切开牛胸肉，粉红色的烟环有一指宽。她说：“还行。下次你自己来。”`,`At three in the morning she hands you coffee and talks about her grandmother in Monterrey. At seven she slices the brisket; the pink smoke ring is a finger wide. "Not bad. Next time you do it."`,`Às três da manhã dá-te um café e fala-te da avó em Monterrey. Às sete corta o peito de vaca; o anel de fumo cor-de-rosa tem um dedo de largura. «Nada mau. Para a próxima fazes tu.»`),t('手艺 +5 · 德州味 +3 · 玛丽索尔：信任 +2 · 精力 −3','Craft +5 · Texanness +3 · Marisol: trust +2 · Energy −3','Ofício +5 · Texanidade +3 · Marisol: confiança +2 · Energia −3'))},
  {t:t('用沙丁鱼的法子跟她比一场','Challenge her with your sardine method','Desafiá-la com o teu método das sardinhas'),req:()=>S.stats.oficio>=35||NEED(t('手艺 35','Craft 35','Ofício 35')),fx:()=>{stat('oficio',3);addLike('marisol',2);S.flags.c1_marisol='duel'},next:()=>c1S(T,t(`你在她的火上烤了四条沙丁鱼。她吃了一条，又吃了一条。“盐好，”她说，“火太急。像你。”`,`You grill four sardines on her fire. She eats one, then another. "Good salt," she says. "Fire's too hasty. Like you."`,`Grelhas quatro sardinhas no lume dela. Ela come uma, depois outra. «Bom sal», diz. «Lume apressado. Como tu.»`),t('手艺 +3 · 玛丽索尔：好感 +2','Craft +3 · Marisol: affection +2','Ofício +3 · Marisol: afeto +2'))},
  {t:t('记笔记，回去自己试','Take notes and try it at home','Tomar notas e experimentar em casa'),fx:()=>{stat('oficio',2);S.flags.c1_marisol='notes'},next:()=>c1S(T,t(`你在餐巾纸上写满了温度和时间。回去试的那块牛胸肉硬得能当门挡。`,`You fill a napkin with times and temperatures. The brisket you try at home comes out hard enough to prop a door.`,`Enches um guardanapo de tempos e temperaturas. O peito que fazes em casa sai tão duro que dava para calçar uma porta.`))}]}}},

/* W6 · Travis at the lot */
{id:'c1_travislot',when:()=>rel('travis').met&&c1AT(6,6,1),run:()=>{const T=t('空地边的皮卡','A pickup by the lot','Uma carrinha junto ao terreno');
 return {title:T,meta:t('第 6 周 · 周六中午','Week 6 · Saturday noon','Semana 6 · Sábado ao meio-dia'),text:[
  t(`你出去倒垃圾，看见一辆黑色皮卡停在空地边上，发动机没熄。特拉维斯站在齐腰的杂草里打电话，另一只手拿着一把卷尺。`,`Taking out the trash, you see a black pickup idling at the edge of the lot. Travis is standing in the waist-high weeds on the phone, a tape measure in his other hand.`,`Ao ires pôr o lixo, vês uma carrinha preta parada à beira do terreno, com o motor ligado. O Travis está no meio das ervas ao telefone, com uma fita métrica na outra mão.`),
  t(`看见你，他挂了电话，笑得很自然：“看看风景。这块地朝向不错，对吧？”你看了看那块地。风景是一座生锈的水塔。`,`When he sees you he hangs up, smiling easy. "Just admiring the view. Nice exposure on this lot, huh?" You look at the lot. The view is a rusted water tower.`,`Quando te vê, desliga e sorri com naturalidade. «Só a apreciar a vista. Este terreno tem boa exposição, hã?» Olhas para o terreno. A vista é uma torre de água ferrugenta.`)],
 choices:[
  {t:t('“风景挺好。不卖。”','"Nice view. Not for sale."','«Bela vista. Não está à venda.»'),fx:()=>{S.flags.c1_travisLot='no';addLike('travis',-1);stat('tex',1)},next:()=>c1S(T,t(`他举起双手：“谁说要买了？兄弟，放轻松。”上车之前，他把卷尺收回去，“啪”的一声很响。`,`He raises both hands. "Who said anything about buying? Easy, brother." Before he gets in, he lets the tape snap back with a loud crack.`,`Levanta as mãos. «Quem falou em comprar? Calma, mano.» Antes de entrar no carro, deixa a fita recolher com um estalo.`))},
  {t:t('请他进来喝杯咖啡','Invite him in for coffee','Convidá-lo para um café'),fx:()=>{addLike('travis',1);S.flags.c1_travisLot='coffee'},next:()=>c1S(T,t(`他喝了咖啡，夸了蛋挞，问了三次你打算在这儿待多久。每次问法都不一样。`,`He drinks the coffee, compliments the tarts and asks you three times how long you plan to stay. Each time in a different way.`,`Bebe o café, elogia os pastéis e pergunta-te três vezes quanto tempo tencionas ficar. Sempre de maneira diferente.`))},
  {t:t('什么都不说，拿手机拍下他的车','Say nothing; photograph his truck','Não dizer nada; fotografar a carrinha'),req:()=>S.stats.tex>=15||NEED(t('德州味 15','Texanness 15','Texanidade 15')),fx:()=>{S.flags.c1_plate=1;stat('tex',2)},next:()=>c1S(T,t(`他看见了，没说什么。车开走以后，你放大照片：车门上贴着一个很新的标志，一颗孤星，下面一行小字被泥糊住了一半。`,`He sees you do it and says nothing. After he drives off you zoom in: a brand-new decal on the door, a lone star, and a line of small print half covered in mud.`,`Ele vê e não diz nada. Depois de ele partir, amplias a fotografia: na porta há um autocolante novinho, uma estrela solitária e uma linha de letras pequenas meio tapada pela lama.`))}]}}},

/* W7 · letter #3 */
{id:'c1_letter3',when:()=>c1AT(7,2,2),run:()=>{const T=t('第三封信','The third letter','A terceira carta');
 return {title:T,meta:t('若泽的菜谱盒','José\'s recipe box','A caixa de receitas do José'),text:[
  t(`你终于整理了若泽的菜谱盒。一沓油腻的卡片：羽衣甘蓝汤、鳕鱼饼、他自己发明的“辣味蛋挞（失败）”。“沙丁鱼”那张后面夹着一个对折的信封：给费尔南达。邮票贴好了，没有邮戳。`,`You finally sort José's recipe box. Greasy index cards: kale soup, salt cod fritters, his own invention "jalapeño custard tart (failed)." Behind the sardine card is a folded envelope: For Fernanda. Stamped. Never postmarked.`,`Finalmente arrumas a caixa de receitas do José. Fichas engorduradas: caldo verde, pastéis de bacalhau, uma invenção dele, «pastel de nata picante (falhado)». Atrás da ficha das sardinhas há um envelope dobrado: Para a Fernanda. Com selo. Sem carimbo.`),
  t(`“费尔南达：休斯敦机场闻起来像地板蜡。这里没有人见过海，我本以为这会让我好受一点。我每天晚上还是梦见驾驶舱，梦见那盏灯。爸爸跟码头上的人怎么说，就让他说吧。他说的那一部分是真的——那天晚上，是我在掌舵。……一九九六年八月。”`,`"Fernanda — the Houston airport smells of floor wax. Nobody here has ever seen the sea. I thought that would make it easier. I still dream of the wheelhouse every night, of that lamp. Let Father tell the harbor whatever he likes. The part he tells is true: that night, I was at the wheel. … August 1996."`,`«Fernanda — o aeroporto de Houston cheira a cera de chão. Aqui ninguém viu o mar. Pensei que isso me aliviasse. Continuo a sonhar todas as noites com a casa do leme, com aquela luz. Deixa o pai dizer no cais o que quiser. A parte que ele conta é verdade: naquela noite, era eu ao leme. … Agosto de 1996.»`)],
 choices:[
  {t:t('把信放回沙丁鱼卡片后面','Put it back behind the sardine card','Voltar a pô-la atrás da ficha das sardinhas'),fx:()=>{c1Letter(3);stat('saud',4)}},
  {t:t('拍下来发给妈妈','Photograph it for Mom','Fotografá-la para a mãe'),fx:()=>{c1Letter(3);stat('saud',6)},next:()=>c1S(T,t(`你打了一行字，删掉，又打了一行，又删掉。最后你只发了一张蛋挞的照片。`,`You type a line, delete it, type another, delete that too. In the end you send her a photo of a custard tart.`,`Escreves uma linha, apagas, escreves outra, apagas também. No fim mandas-lhe uma fotografia de um pastel de nata.`),t('若泽的第 3 封信 · 乡愁 +6','José\'s letter #3 · Homesickness +6','Carta n.º 3 do José · Saudade +6'))},
  {t:t('照着那张沙丁鱼卡片做一次','Cook from the sardine card','Fazer as sardinhas pela ficha'),fx:()=>{c1Letter(3);stat('oficio',2);S.lusoThisWeek=true},next:()=>c1S(T,t(`卡片背面有一行小字：“盐要比你想的多一点。妈妈说的。”这是外婆的做法。你照做了，味道和你小时候一模一样。`,`On the back of the card, in small writing: "More salt than you think. Mother's rule." Your grandmother's recipe. You follow it, and it tastes exactly like your childhood.`,`No verso da ficha, em letra pequena: «Mais sal do que achas. Regra da mãe.» A receita da tua avó. Segues à risca, e sabe exatamente à tua infância.`),t('若泽的第 3 封信 · 手艺 +2','José\'s letter #3 · Craft +2','Carta n.º 3 do José · Ofício +2'))}]}}},

/* W7 · cattle drive */
{id:'c1_cattle',when:()=>!!S.flags.ranch&&c1AT(7,6,0),run:()=>{const T=t('赶牛','The cattle drive','A condução do gado');
 return {title:T,meta:t('雷耶斯牧场 · 周六黎明','Reyes Ranch · Saturday dawn','Rancho Reyes · Sábado de madrugada'),text:[
  t(`清晨五点，露西娅敲你的窗：“韦德病了，我们缺一个人。你会骑马吗？——算了，你会走路吗？”`,`Five in the morning, Lucía knocks on your window. "Wade's sick and we're a hand short. Can you ride? — Never mind. Can you walk?"`,`Às cinco da manhã, a Lucía bate-te à janela. «O Wade está doente e falta-nos um. Sabes montar? — Esquece. Sabes andar?»`),
  t(`雷耶斯家要把两百头牛从南边的草场赶到河边。天还没亮，贝托已经在马背上了。`,`The Reyes family is moving two hundred head from the south pasture down to the river. It isn't light yet, and Beto is already in the saddle.`,`Os Reyes vão levar duzentas cabeças de gado da pastagem sul até ao rio. Ainda não é dia e o Beto já está montado.`)],
 choices:[
  {t:t('骑马跟着赶','Ride with them','Ir a cavalo'),req:()=>S.course.ride>=1||NEED(t('骑马课 1','Riding lesson 1','Aula de equitação 1')),fx:()=>{stat('tex',6);addTrust('lucia',2);addTrust('beto',1);S.flags.c1_cattle='ride';c1Tired(2)},next:()=>c1S(T,t(`你的马比你懂。中午到河边的时候，你的大腿已经不是你的了。贝托骑到你旁边：“若泽骑得比你差。”这是他说过最接近夸奖的话。`,`Your horse knows more than you do. By the time you reach the river at noon, your thighs belong to someone else. Beto rides up beside you. "José rode worse than you." It's the closest he's ever come to a compliment.`,`O cavalo sabe mais do que tu. Quando chegam ao rio, ao meio-dia, as tuas coxas já são de outra pessoa. O Beto põe-se ao teu lado. «O José montava pior do que tu.» É o mais perto de um elogio que alguma vez disse.`),t('德州味 +6 · 露西娅：信任 +2 · 贝托：信任 +1','Texanness +6 · Lucía: trust +2 · Beto: trust +1','Texanidade +6 · Lucía: confiança +2 · Beto: confiança +1'))},
  {t:t('开皮卡跟在后面','Follow in the pickup','Ir atrás na carrinha'),req:()=>S.course.drive>=1||NEED(t('驾驶课 1','Driving lesson 1','Aula de condução 1')),fx:()=>{stat('tex',4);addTrust('beto',1);addLike('lucia',1);S.flags.c1_cattle='truck'},next:()=>c1S(T,t(`一头小牛跑丢了，你开着皮卡追了它两公里，在一片仙人掌后面找到了它。露西娅说：“城里人，还有点用。”`,`A calf breaks away; you chase it two kilometers in the pickup and find it behind a stand of prickly pear. Lucía says, "City boy's good for something."`,`Um vitelo foge; persegues-o dois quilómetros de carrinha e encontra-lo atrás de uns cactos. A Lucía diz: «O menino da cidade sempre serve para alguma coisa.»`))},
  {t:t('走路，负责开关铁门','Go on foot and work the gates','Ir a pé e tratar dos portões'),fx:()=>{stat('tex',3);addLike('lucia',1);S.flags.c1_cattle='walk';c1Tired(2)},next:()=>c1S(T,t(`你守着铁门走了六个小时土路。最后一头牛进圈的时候，所有人都给你鼓掌——带着一点讽刺，也带着一点真心。`,`Six hours on a dirt road, minding gates. When the last cow goes through, everybody applauds you — a little sarcastic, a little sincere.`,`Seis horas em estrada de terra, a guardar portões. Quando passa a última vaca, todos te aplaudem — um bocadinho a gozar, um bocadinho a sério.`))},
  {t:t('说店里离不开人','Say you can\'t leave the shop','Dizer que não podes deixar o restaurante'),fx:()=>{addTrust('lucia',-1);S.flags.c1_cattle='no'},next:()=>c1S(T,t(`露西娅点点头，什么都没说就走了。`,`Lucía nods and leaves without a word.`,`A Lucía acena e vai-se embora sem uma palavra.`))}]}}},

/* W8 · the "Spanish guitarist" */
{id:'c1_quince',when:()=>c1AT(8,3,1),run:()=>{const T=t('请来的“西班牙吉他手”','The "Spanish guitarist"','O «guitarrista espanhol»');
 return {title:T,meta:t('文化误会','Culture clash','Choque cultural'),text:[
  t(`一位太太打电话订席：女儿的十五岁生日宴，要“一个西班牙吉他手，弹弗拉明戈，最好长得帅”。她听说你店里有个“欧洲小伙子会弹琴”。`,`A woman calls to book: her daughter's quinceañera, and she wants "a Spanish guitar player, flamenco, handsome if possible." She's heard there's "a European boy with a guitar" at your place.`,`Uma senhora liga a reservar: a festa dos quinze anos da filha, e quer «um guitarrista espanhol, flamenco, se possível bonito». Ouviu dizer que no teu restaurante há «um rapaz europeu que toca guitarra».`),
  t(`你说你是葡萄牙人，弹的是法多，法多是悲伤的歌。她说：“甜心，悲伤的也行，只要是欧洲的。”`,`You explain you're Portuguese, you play fado, and fado is sad music. "Sugar," she says, "sad is fine, long as it's European."`,`Explicas que és português, tocas fado, e o fado é triste. «Querido», diz ela, «triste também serve, desde que seja europeu.»`)],
 choices:[
  {t:t('接下来，去唱法多','Take it, and sing fado','Aceitar e cantar fado'),fx:()=>{S.cash+=150;S.rep+=3;stat('saud',3);S.lusoThisWeek=true},next:()=>c1S(T,t(`你唱了一首关于大海和离别的法多。十五岁的女孩哭了，她妈妈哭了，连厨子都哭了。你收了一百五十块，被拥抱了二十多次。`,`You sing a fado about the sea and leaving. The fifteen-year-old cries, her mother cries, even the cook cries. You're paid $150 and hugged more than twenty times.`,`Cantas um fado sobre o mar e a partida. A menina de quinze anos chora, a mãe chora, até o cozinheiro chora. Recebes 150 dólares e mais de vinte abraços.`),t('现金 +$150 · 口碑 +3','Cash +$150 · Reputation +3','Dinheiro +$150 · Reputação +3'))},
  {t:`[${faceWord()}] `+t('接下来，速成三首弗拉明戈','Take it, and cram three flamenco songs','Aceitar e aprender três flamencos à pressa'),req:CHARM_REQ(55),fx:()=>{S.cash+=200;S.rep+=2;stat('tex',1);flirt()},next:()=>c1S(T,t(`你看视频学了三天。弹得很烂，但你在台上甩头发的样子让所有阿姨都很满意。回家路上，你觉得自己有点像个骗子。`,`Three days of video tutorials. You play terribly, but the way you toss your hair on stage satisfies every auntie in the room. Walking home, you feel a bit like a fraud.`,`Três dias de vídeos. Tocas muito mal, mas a maneira como sacodes o cabelo no palco deixa todas as tias satisfeitas. A caminho de casa, sentes-te um bocadinho impostor.`),t('现金 +$200','Cash +$200','Dinheiro +$200'))},
  {t:t('推荐她请墨西哥乐队，你来包办酒席','Suggest a real mariachi band, and cater it yourself','Sugerir um grupo de mariachis e tratar tu da comida'),req:()=>S.stats.oficio>=30||NEED(t('手艺 30','Craft 30','Ofício 30')),fx:()=>{S.cash+=220;S.rep+=4;stat('tex',3)},next:()=>c1S(T,t(`乐队唱墨西哥情歌，你烤了六十个猪排包。主唱吃完拍拍你：“兄弟，下次你唱，我们伴奏。”`,`The band sings Mexican love songs while you grill sixty pork sandwiches. The lead singer pats your back afterward. "Next time, brother, you sing and we'll back you."`,`O grupo canta canções de amor mexicanas e tu grelhas sessenta bifanas. No fim, o vocalista dá-te uma palmada. «Para a próxima, mano, cantas tu e nós acompanhamos.»`),t('现金 +$220 · 口碑 +4 · 德州味 +3','Cash +$220 · Reputation +4 · Texanness +3','Dinheiro +$220 · Reputação +4 · Texanidade +3'))}]}}},

/* W10 · letter #4 */
{id:'c1_letter4',when:()=>c1AT(10,3,2),run:()=>{const T=t('围裙口袋','The apron pocket','O bolso do avental');
 return {title:T,meta:t('第四封信','The fourth letter','A quarta carta'),text:[
  t(`厨房门后挂着若泽的围裙，十个星期你一直没碰。今晚你的围裙没干，你把他的取了下来。很重。口袋里有一副老花镜、三个打火机、一张一九九七年的罐头厂工牌——照片上的若泽比你现在还年轻——和一封叠成小方块的信。`,`José's apron has hung behind the kitchen door for ten weeks and you've never touched it. Tonight yours is still wet, so you take his down. It's heavy. In the pocket: reading glasses, three lighters, a 1997 cannery ID badge — José in the photo is younger than you are now — and a letter folded into a small square.`,`O avental do José está pendurado atrás da porta da cozinha há dez semanas e nunca lhe tocaste. Esta noite o teu ainda está molhado, por isso tiras o dele. É pesado. No bolso: uns óculos de ler, três isqueiros, um cartão da fábrica de conservas de 1997 — o José da fotografia é mais novo do que tu agora — e uma carta dobrada num quadradinho.`),
  t(`“费尔南达：我现在每天剖两千条鱼，在一个离海四百公里的地方。上帝是有幽默感的。工头说我手快，以前一定干过。我说干过，在船上。他问什么船，我说一条沉了的船。他就不问了——这里的人，每个人都有一条沉了的船。钱我会寄回去，别告诉爸爸是我寄的。他宁可要债主，也不要我。……一九九七年十二月。”`,`"Fernanda — I gut two thousand fish a day now, two hundred and fifty miles from the sea. God has a sense of humor. The foreman says I'm quick, I must have done this before. I said yes, on a boat. He asked what boat, I said one that sank. He didn't ask again — everyone here has a boat that sank. I'll send money. Don't tell Father it's from me. He'd rather have the creditors than me. … December 1997."`,`«Fernanda — agora estripo dois mil peixes por dia, a quatrocentos quilómetros do mar. Deus tem sentido de humor. O capataz diz que tenho mãos rápidas, que já devo ter feito isto. Disse que sim, num barco. Perguntou que barco, disse que um que foi ao fundo. Não perguntou mais — aqui todos têm um barco que foi ao fundo. Vou mandar dinheiro. Não digas ao pai que é meu. Ele prefere os credores a mim. … Dezembro de 1997.»`)],
 choices:[
  {t:t('系上他的围裙开工','Tie on his apron and get to work','Pôr o avental dele e ir trabalhar'),fx:()=>{c1Letter(4);stat('oficio',2);stat('saud',3);S.flags.c1_apron=1},next:()=>c1S(T,t(`围裙对你来说太大了。你把带子多绕了一圈，系紧。`,`The apron is too big for you. You wrap the strings around one extra time and pull them tight.`,`O avental é grande demais para ti. Dás mais uma volta às fitas e apertas bem.`),t('若泽的第 4 封信 · 手艺 +2','José\'s letter #4 · Craft +2','Carta n.º 4 do José · Ofício +2'))},
  {t:t('把工牌夹进账本','Tuck the badge into the ledger','Guardar o cartão no livro de contas'),fx:()=>{c1Letter(4);stat('saud',3);S.flags.c1_badge=1},next:()=>c1S(T,t(`工牌背面用圆珠笔写着一个电话号码，后面跟着一个姓：菲茨杰拉德。你不知道这是谁。`,`On the back of the badge, in ballpoint: a phone number, and after it a surname — Fitzgerald. You don't know who that is.`,`No verso do cartão, a esferográfica: um número de telefone e, a seguir, um apelido — Fitzgerald. Não sabes quem é.`),t('若泽的第 4 封信','José\'s letter #4','Carta n.º 4 do José'))},
  {t:t('给鲁伊发消息：“外公以前有船吗？”','Text Rui: "Did Grandpa have a boat?"','Mandar mensagem ao Rui: «O avô tinha um barco?»'),fx:()=>{c1Letter(4);stat('saud',5);S.flags.c1_askedRui=1},next:()=>c1S(T,t(`过了很久，鲁伊回了一句：“妈说别问。你问这个干嘛？”`,`A long time later Rui writes back: "Mom says don't ask. Why do you want to know?"`,`Muito tempo depois, o Rui responde: «A mãe diz para não perguntares. Porque queres saber?»`),t('若泽的第 4 封信 · 乡愁 +5','José\'s letter #4 · Homesickness +5','Carta n.º 4 do José · Saudade +5'))}]}}},

/* W11 · fireworks in the lot */
{id:'c1_fireworks',when:()=>c1AT(11,6,2),run:()=>{const T=t('空地上的烟花','Fireworks in the lot','Foguetes no terreno');
 return {title:T,meta:t('第 11 周 · 周六夜','Week 11 · Saturday night','Semana 11 · Sábado à noite'),text:[
  t(`后门外一声巨响。你冲出去，看见汤米和小戴尔站在空地中间，脚边一圈干草正在冒烟。“我们只是试一下！七月四号要用的！”`,`A bang behind the shop. You run out to find Tommy and Little Dale in the middle of the lot, a ring of dry grass smoking at their feet. "We were just testing! They're for the Fourth!"`,`Um estrondo atrás do restaurante. Corres lá fora e vês o Tommy e o pequeno Dale no meio do terreno, com um círculo de erva seca a fumegar aos pés. «Estávamos só a testar! São para o 4 de Julho!»`),
  t(`火苗窜得比你想的快。远处传来警笛——是普鲁伊特警长的巡逻车。`,`The flames spread faster than you'd think. Somewhere a siren starts up — Sheriff Pruitt's cruiser.`,`As chamas espalham-se mais depressa do que pensavas. Ao longe ouve-se uma sirene — o carro do xerife Pruitt.`)],
 choices:[
  {t:t('拖水管冲过去灭火','Drag the hose over and put it out','Puxar a mangueira e apagar o fogo'),fx:()=>{stat('tex',2);S.rep+=1;S.flags.c1_lotSign=1;log('在空地里找到一块旧罐头厂的界牌','Found an old cannery boundary sign in the lot','Encontraste uma placa antiga da fábrica no terreno')},next:()=>c1S(T,t(`火灭了。你在烧焦的草里踩到一块铁牌，褪色的字写着：“圣鲁伊斯罐头厂 · 厂界 · 禁止入内”。你把它擦干净，靠在塑料椅旁边。警长到的时候，两个孩子早跑了。`,`The fire's out. In the scorched grass your foot hits a metal plate, its letters faded: "SAN LUÍS PACKING CO. · PROPERTY LINE · NO TRESPASSING." You wipe it off and lean it against the plastic chair. By the time the sheriff arrives, the boys are long gone.`,`O fogo apaga-se. Na erva queimada tropeças numa placa de metal com letras desbotadas: «SAN LUÍS PACKING CO. · LIMITE DA PROPRIEDADE · ENTRADA PROIBIDA». Limpas-a e encostas-a à cadeira de plástico. Quando o xerife chega, os miúdos já desapareceram.`))},
  {t:t('替孩子们扛下来：“是我在试烟花。”（罚款 $50）','Take the blame: "I was the one testing them." ($50 fine)','Assumir a culpa: «Fui eu que estava a testar.» (multa de $50)'),req:MONEY(50),fx:()=>{S.flags.c1_lotSign=1;S.flags.c1_coverKids=1;stat('tex',1);log('在空地里找到一块旧罐头厂的界牌','Found an old cannery boundary sign in the lot','Encontraste uma placa antiga da fábrica no terreno')},next:()=>c1S(T,t(`警长看了你很久，开了一张五十块的罚单。第二天小戴尔来店里，放下五十块钱和一张纸条：“谢谢。别告诉我爸。”纸条背面写着：“你们空地里有块牌子，我们踢到的。”`,`The sheriff studies you a long while and writes a fifty-dollar ticket. Next day Little Dale comes in, sets down fifty dollars and a note: "Thanks. Don't tell my dad." On the back: "There's a sign in your lot. We kicked it."`,`O xerife olha para ti muito tempo e passa uma multa de cinquenta dólares. No dia seguinte o pequeno Dale aparece, deixa cinquenta dólares e um bilhete: «Obrigado. Não digas ao meu pai.» No verso: «Há uma placa no vosso terreno. Demos-lhe um pontapé.»`))},
  {t:t('冲他们大喊，让他们自己收拾','Yell at them to clean up their own mess','Gritar-lhes para resolverem a asneira'),fx:()=>{stat('tex',1);S.rep-=1},next:()=>c1S(T,t(`两个孩子提着水桶跑了二十趟。警长到的时候，空地上只剩一股焦味和两个满脸烟灰、一本正经的高中生。他什么都没说，只看了一眼那块空地，又看了一眼你。`,`The two boys run twenty trips with buckets. When the sheriff pulls up there's nothing left but the smell of burning and two soot-faced, very serious teenagers. He says nothing. He looks at the lot, then at you.`,`Os dois miúdos fazem vinte viagens com baldes. Quando o xerife chega, só resta o cheiro a queimado e dois adolescentes muito sérios, de cara cheia de fuligem. Ele não diz nada. Olha para o terreno, depois para ti.`))}]}}},

/* W12 · Grace and the sealed annex */
{id:'c1_grace',when:()=>c1AT(12,2,1),run:()=>{const T=t('四分之一','A quarter of the way','Um quarto do caminho');S.flags.c1_sealed=1;
 return {title:T,meta:t('格蕾丝 · 遗嘱执行','Grace · The estate','Grace · A herança'),text:[
  t(`格蕾丝点了一杯黑咖啡，把文件摊开。“十二周。遗嘱执行顺利，你一天都没离开。”她停了一下。`,`Grace orders black coffee and spreads out her file. "Twelve weeks. The estate's in order and you haven't left town once." She pauses.`,`A Grace pede um café simples e abre a pasta. «Doze semanas. A herança está em ordem e não saíste da vila um único dia.» Faz uma pausa.`),
  t(`“还有一件事。地契的附件里有一页，若泽签字时要求单独封存，我无权打开。封条上只写着：与一九九八年和解相关。我本来不想说，但我觉得你应该知道它存在。”`,`"One more thing. There's a page annexed to the deed that José had sealed separately when he signed. I'm not authorized to open it. The seal just says: re the 1998 settlement. I wasn't going to mention it, but I think you should know it exists."`,`«Mais uma coisa. Há uma página anexa à escritura que o José mandou selar à parte quando assinou. Não tenho autorização para a abrir. O selo diz só: relativo ao acordo de 1998. Não ia dizer nada, mas acho que deves saber que existe.»`)],
 choices:[
  {t:t('认真地问：“什么和解？”','Ask seriously: "What settlement?"','Perguntar a sério: «Que acordo?»'),fx:()=>addTrust('grace',1),next:()=>c1S(T,t(`“我不知道。我只知道封存它的人不是若泽的律师，是罐头厂的。”她合上文件，“我会查。慢慢查。”`,`"I don't know. I only know the lawyer who sealed it wasn't José's. It was the cannery's." She closes the file. "I'll look into it. Carefully."`,`«Não sei. Só sei que quem o selou não foi o advogado do José. Foi o da fábrica.» Fecha a pasta. «Vou investigar. Com calma.»`))},
  {t:t('开个玩笑：“只要不是欠债就行。”','Joke: "As long as it isn\'t debt."','Brincar: «Desde que não seja uma dívida.»'),fx:()=>addLike('grace',1),next:()=>c1S(T,t(`她没笑，但嘴角动了一下。“我也希望不是。”`,`She doesn't laugh, but the corner of her mouth moves. "I hope not too."`,`Não se ri, mas o canto da boca mexe-se. «Também espero que não.»`))},
  {t:`[${faceWord()}] `+t('“你是专门来告诉我这个，还是来看我的？”','"Did you come to tell me that, or to see me?"','«Vieste dizer-me isto ou vieste ver-me?»'),req:CHARM_REQ(50),fx:()=>{addLike('grace',2);flirt()},next:()=>c1S(T,t(`“我是来喝咖啡的，”她说，“咖啡很难喝。”然后她又点了一杯。`,`"I came for the coffee," she says. "The coffee is terrible." Then she orders another.`,`«Vim pelo café», diz ela. «O café é péssimo.» E pede outro.`))}]}}},

/* W12 · the night before the Fourth */
{id:'c1_eve',when:()=>c1AT(12,5,2),run:()=>{const T=t('七月四日前夜','The night before the Fourth','A véspera do 4 de Julho');
 const NAMES={albertina:['阿尔贝蒂娜太太','Dona Albertina','a Dona Albertina'],earl:['厄尔','Earl','o Earl'],lucia:['露西娅','Lucía','a Lucía'],savannah:['萨凡纳','Savannah','a Savannah'],beto:['贝托','Beto','o Beto'],marisol:['玛丽索尔','Marisol','a Marisol'],grace:['格蕾丝','Grace','a Grace']};
 const help=Object.keys(NAMES).filter(k=>rel(k).met&&(rel(k).like>=4||rel(k).trust>=4));
 if(S.flags.c1_wifi==='work'||S.flags.c1_coverKids)help.push('kids');
 const nm=i=>help.map(k=>k==='kids'?['汤米和小戴尔','Tommy and Little Dale','o Tommy e o pequeno Dale'][i]:NAMES[k][i]);
 const list=i=>{const a=nm(i);if(i===0)return a.join('、');return a.length<2?a.join(''):a.slice(0,-1).join(', ')+(i===1?' and ':' e ')+a[a.length-1]};
 const n=help.length;S.flags.c1_helpers=n;
 const who=n?t(`晚上九点，后门陆续有人进来：${list(0)}。没人打招呼，每个人进门就找活干。`,`At nine the back door starts opening: ${list(1)}. Nobody says hello; everybody walks in and finds something to do.`,`Às nove, a porta das traseiras começa a abrir-se: ${list(2)}. Ninguém cumprimenta; cada um entra e arranja logo o que fazer.`):t(`没有人来。只有你、收音机，和若泽那台用铁丝绑着的烤架。`,`Nobody comes. Just you, the radio, and José's grill held together with wire.`,`Não aparece ninguém. Só tu, o rádio e a grelha do José presa com arame.`);
 return {title:T,meta:t('第 12 周 · 周五夜','Week 12 · Friday night','Semana 12 · Sexta à noite'),text:[
  t(`明天就是集市。厨房里堆着二十公斤沙丁鱼、两百个蛋挞皮、一桶腌好的猪排。还有一整夜的活。后门开着，热风灌进来，远处已经有人在试烟花。`,`The fair is tomorrow. The kitchen is stacked with forty pounds of sardines, two hundred tart shells and a tub of marinating pork. There's a whole night of work left. The back door is open, hot wind pouring in; somewhere, somebody's already testing fireworks.`,`A feira é amanhã. Na cozinha há vinte quilos de sardinhas, duzentas formas de pastel de nata e um alguidar de porco a marinar. Ainda há uma noite inteira de trabalho. A porta das traseiras está aberta, entra vento quente; algures já há quem teste foguetes.`),
  who],
 choices:[
  {t:t('埋头干到天亮','Keep your head down and work till dawn','Trabalhar de cabeça baixa até de manhã'),fx:()=>{stat('oficio',3);S.rep+=1;S.flags.c1_eve='work';c1Tired(3)},next:()=>c1S(T,t(`天亮的时候，两百个蛋挞整整齐齐排在烤盘上，像一支等着检阅的小军队。`,`By dawn two hundred tarts sit in neat rows on the trays like a little army awaiting inspection.`,`Ao amanhecer, duzentos pastéis alinham-se nos tabuleiros como um pequeno exército à espera de revista.`),t('手艺 +3 · 精力 −3','Craft +3 · Energy −3','Ofício +3 · Energia −3'))},
  {t:t('停下来，和来帮忙的人在后门喝一杯','Stop, and have a drink on the back step with your helpers','Parar e beber um copo nas traseiras com quem veio ajudar'),req:()=>n>=2||NEED(t('至少两个人来帮忙','At least two helpers','Pelo menos duas pessoas a ajudar')),fx:()=>{help.forEach(k=>{if(k!=='kids')addLike(k,1)});stat('tex',2);S.rep+=2;S.flags.c1_eve='friends'},next:()=>c1S(T,t(`你们坐在后门台阶上，塑料椅让给了年纪最大的人。空地里的萤火虫又出来了。有人问：“你明天到底卖什么？”你还没想好。但你第一次觉得，不管卖什么，都有人会来。`,`You all sit on the back step; the plastic chair goes to the oldest. The fireflies are out in the lot again. Someone asks, "So what are you actually selling tomorrow?" You haven't decided. But for the first time you feel that whatever it is, people will come.`,`Sentam-se todos no degrau das traseiras; a cadeira de plástico fica para o mais velho. Os pirilampos voltaram ao terreno. Alguém pergunta: «Então, o que vais vender amanhã?» Ainda não decidiste. Mas pela primeira vez sentes que, seja o que for, vai aparecer gente.`),t('来帮忙的人：好感 +1 · 口碑 +2','Helpers: affection +1 · Reputation +2','Quem ajudou: afeto +1 · Reputação +2'))},
  {t:t('给里斯本打个电话','Call Lisbon','Ligar para Lisboa'),fx:()=>{stat('saud',4);S.lusoThisWeek=true;S.flags.c1_eve='call'},next:()=>c1S(T,t(`里斯本是早上六点，妈妈刚醒。你说明天是美国的国庆节。她说：“那你记得穿件干净衬衫。”你笑了，然后发现自己眼睛有点湿。`,`It's six in the morning in Lisbon; Mom has just woken up. You tell her tomorrow is America's Independence Day. "Then wear a clean shirt," she says. You laugh, and then notice your eyes are wet.`,`Em Lisboa são seis da manhã; a mãe acabou de acordar. Dizes-lhe que amanhã é o dia da independência americana. «Então veste uma camisa lavada», diz ela. Ris-te, e depois reparas que tens os olhos húmidos.`),t('乡愁 +4','Homesickness +4','Saudade +4'))}]}}}

);
